import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int p = scanner.nextInt();
        int k = scanner.nextInt();
        long MOD = 1000000007L;

        if (k == 0) {
            long result = powMod(p, p - 1, MOD);
            System.out.println(result);
        } else if (k == 1) {
            long result = powMod(p, p, MOD);
            System.out.println(result);
        } else {
            long product_mod = 1;
            int i;
            for (i = 1; i <= p; i++) {
                product_mod = (product_mod * k) % p;
                if (product_mod == 1) {
                    break;
                }
            }
            long exponent = (p - 1) / i;
            System.out.println(powMod(p, exponent, MOD));
        }
        scanner.close();
    }

    private static long powMod(long base, long exp, long mod) {
        long result = 1;
        base = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }
}
